select cdr_id,cdr_type,partner,owner,iccid,first_installed,profile_type,eid,sim_type,cp_id,service_id,before_sharing,price_rate_type,network_type,invoicing_co_id,share_basis,cdr_filename,chk_duplicate,filter_dtm,create_by,remap_dtm,remap_by,process_date,transaction_units,status,workflow_process_date,SYSDATE as bld_export_date,file_date from <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.tb_transaction_ss_esim_valid where workflow_process_date > TO_CHAR(SYSDATE-INTERVAL '7' DAY, 'YYYYMMDDHH24MISS') and workflow_process_date > (select coalesce(max_workflow_process_date_mssql,'00000000000000') as max_workflow_process_date_mssql from <%=odiRef.getSchemaName("DSS_ODI_LOG","D")%>.ext_dss_checkpoint_tb_transaction_ss_esim_valid)